const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { FakeDocument } = require('./browser-fakes.js');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');

const scripts = process.env.WORKBENCH_SCRIPT_DIR
    || path.resolve(__dirname, '../../tools/workbench/src/main/webapp/scripts');

function loadWorkbench() {
    const workbench = {};
    const window = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, Promise, window, workbench, setTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        vm.runInContext(fs.readFileSync(path.join(scripts, filename), 'utf8'), context, { filename });
    }
    window.workbench = context.workbench;
    return { workbench: context.workbench, window, context };
}

function flatten(template) {
    if (Array.isArray(template)) {
        return template.map(flatten).join('');
    }
    if (template && Array.isArray(template.strings)) {
        return template.strings.reduce((result, fragment, index) => result + fragment
            + (index < template.values.length ? flatten(template.values[index]) : ''), '');
    }
    if (template && template.tagName) {
        const attributes = Array.from(template.attributes.entries())
            .map(([name, value]) => `${name}="${value}"`).join(' ');
        return `<${template.tagName.toLowerCase()} ${attributes}>${flatten(template.template)}</${template.tagName.toLowerCase()}>`;
    }
    return template === null || typeof template === 'undefined' ? '' : String(template);
}

/** The rendered route template: the outlet's template when the shell renders the route into an outlet. */
function routeTemplate(workbench, mount) {
    const outlet = workbench.views.outletOf ? workbench.views.outletOf(mount) : null;
    return outlet && outlet.template ? outlet.template : mount.template;
}

function windowHarness(workbench, window, model) {
    const document = new FakeDocument();
    const mount = document.createElement('main');
    const listeners = new Map();
    const renders = [];
    const controls = { expanded: false, resource: '<urn:initial>', limit: '100', showDatatypes: true };
    window.innerHeight = 220;
    window.scrollY = 0;
    window.addEventListener = (name, listener) => listeners.set(name, listener);
    window.removeEventListener = name => listeners.delete(name);
    const geometry = document.createElement(model.viewId === 'saved-queries' ? 'div' : 'table');
    geometry.getBoundingClientRect = () => ({ top: -window.scrollY,
        height: model.rowCount * (model.viewId === 'saved-queries' ? 240 : 44) });
    const originalQuery = mount.querySelectorAll.bind(mount);
    mount.querySelectorAll = selector => selector.includes('data-workbench-row-table')
        || selector.includes('data-workbench-row-list') ? [geometry] : originalQuery(selector);

    const applyAttributes = (element, markup) => {
        for (const match of markup.matchAll(/([\w-]+)=(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g)) {
            element.setAttribute(match[1], match[2] ?? match[3] ?? match[4]);
        }
    };
    const nodeValues = (template, nodes = []) => {
        if (template && template.tagName) {
            nodes.push(template);
        } else if (Array.isArray(template)) {
            template.forEach(value => nodeValues(value, nodes));
        } else if (template && template.values) {
            template.values.forEach(value => nodeValues(value, nodes));
        }
        return nodes;
    };
    const renderCard = (card, markup) => {
        for (const match of markup.matchAll(/<form\b([^>]*data-workbench-query-execution="true"[^>]*)>/g)) {
            const form = document.createElement('form');
            applyAttributes(form, match[1]);
            card.appendChild(form);
        }
    };
    const renderer = {
        nothing: '',
        html: runtime().html,
        render(template, target) {
            renders.push(target);
            target.template = template;
            const previousButtons = target.querySelectorAll('[data-workbench-explore-action]');
            target.children.slice().forEach(child => target.removeChild(child));
            nodeValues(template).forEach(node => target.appendChild(node));
            const markup = flatten(template);
            if (target === mount) {
                Object.assign(controls,
                    { expanded: false, resource: '<urn:initial>', limit: '100', showDatatypes: true });
                document.activeElement = null;
                const focusControl = document.createElement('input');
                focusControl.id = 'edited-control';
                target.appendChild(focusControl);
                if (!nodeValues(template).length) {
                    for (const match of markup.matchAll(/<article\b([^>]*)>([\s\S]*?)<\/article>/g)) {
                        const card = document.createElement('article');
                        applyAttributes(card, match[1]);
                        renderCard(card, match[2]);
                        target.appendChild(card);
                    }
                }
            } else if (target.tagName === 'ARTICLE') {
                renderCard(target, markup);
            }
            if (target === mount && nodeValues(template).length) { return; }
            for (const match of markup.matchAll(/<button\b([^>]*data-workbench-explore-action=[^>]*)>/g)) {
                const probe = document.createElement('button');
                applyAttributes(probe, match[1]);
                const button = previousButtons.find(candidate => target !== mount
                    && candidate.getAttribute('data-workbench-explore-action') === probe.getAttribute('data-workbench-explore-action')
                    && candidate.getAttribute('data-workbench-explore-group') === probe.getAttribute('data-workbench-explore-group')) || probe;
                applyAttributes(button, match[1]);
                target.appendChild(button);
            }
        }
    };
    return { document, mount, renderer, controls, listeners, renders, nodeValues };
}

test('saved-query bindings retain overlapping cards and dispose queries leaving the row window', async () => {
    const { workbench, window } = loadWorkbench();
    const rows = Array.from({ length: 300 }, (_unused, index) => [
        `urn:saved:${index}`, `Query ${index}`, 'me', 'SELECT * WHERE { ?s ?p ?o }', 'SPARQL', 'true', '100', '0'
    ]);
    const model = modelFor('saved-queries', []);
    model.vars = ['query', 'queryName', 'user', 'queryText', 'queryLn', 'infer', 'rowsPerPage', 'queryTimeout'];
    model.rowCount = rows.length;
    model.rowStore = { async read(start, count) { return rows.slice(start, start + count); } };
    const harness = windowHarness(workbench, window, model);
    const bindings = new Map();
    const disposed = [];
    workbench.queryStream.bindExecutionForms = root => {
        const forms = root.querySelectorAll('form[data-workbench-query-execution="true"]');
        for (const [form, binding] of bindings) {
            if (!forms.includes(form)) {
                disposed.push(binding.id);
                bindings.delete(form);
            }
        }
        forms.forEach(form => {
            if (!bindings.has(form)) {
                bindings.set(form, { id: form.id, submissions: 0 });
                form.addEventListener('submit', () => bindings.get(form).submissions++);
            }
        });
        return () => {
            bindings.forEach(binding => disposed.push(binding.id));
            bindings.clear();
        };
    };
    workbench.views.render(harness.mount, model, context, harness.renderer);
    const dispose = await workbench.views.bindRowWindows(harness.mount, model, context, harness.renderer);
    const firstForm = Array.from(bindings.keys()).find(form => form.id === 'saved-query-exec-0');
    assert.ok(firstForm, 'initial saved queries must have execution bindings');
    const firstBinding = bindings.get(firstForm);
    window.innerHeight = 660;
    await harness.listeners.get('resize')();
    assert.equal(bindings.get(firstForm), firstBinding,
        'resize must retain the controller for the same visible query');
    assert.equal(disposed.length, 0, 'resize must not cancel active visible queries');
    const overlappingForm = Array.from(bindings.keys()).find(form => form.id === 'saved-query-exec-4');
    const overlappingBinding = bindings.get(overlappingForm);
    window.scrollY = 8 * 240;
    await harness.listeners.get('scroll')();
    assert.equal(bindings.get(overlappingForm), overlappingBinding,
        'a query remaining in the shifted window must keep its own controller');
    assert.ok(disposed.includes('saved-query-exec-0'), 'removed queries must release their controllers');
    const laterForm = Array.from(bindings.keys()).find(form => form.id === 'saved-query-exec-8');
    assert.ok(laterForm, 'newly visible queries must acquire execution bindings');
    assert.notEqual(laterForm, firstForm, 'a former query form must not be repurposed for another query');
    laterForm.trigger('submit');
    assert.equal(bindings.get(laterForm).submissions, 1, 'new bindings must execute exactly once');
    assert.ok(bindings.size <= 80, 'card and controller retention must stay within the row window');
    dispose();
    assert.equal(bindings.size, 0);
    assert.equal(harness.listeners.size, 0);
});

test('Explore group navigation completes when resize changes the viewport during its summary scan', async () => {
    const { workbench, window } = loadWorkbench();
    const rows = Array.from({ length: 300 }, (_unused, index) => [
        { kind: 'iri', value: 'urn:example:resource' },
        { kind: 'iri', value: index < 80 ? 'http://www.w3.org/2000/01/rdf-schema#range' : 'urn:predicate' },
        { kind: 'iri', value: `urn:range:${String(index).padStart(3, '0')}` }
    ]);
    const model = modelFor('explore', []);
    model.rowCount = rows.length;
    let releaseScan;
    let blockScan = false;
    model.rowStore = {
        read(start, count) {
            if (blockScan && start === 0 && count === 256) {
                blockScan = false;
                return new Promise(resolve => { releaseScan = () => resolve(rows.slice(start, start + count)); });
            }
            return Promise.resolve(rows.slice(start, start + count));
        }
    };
    const harness = windowHarness(workbench, window, model);
    workbench.views.render(harness.mount, model, context, harness.renderer);
    const dispose = await workbench.views.bindRowWindows(harness.mount, model, context, harness.renderer);
    const next = harness.mount.querySelectorAll('[data-workbench-explore-action]').find(button =>
        button.getAttribute('data-workbench-explore-group') === 'range'
        && button.getAttribute('data-workbench-explore-action') === 'next');
    assert.ok(next, 'the complete summary must bind its group navigation controls');
    blockScan = true;
    next.trigger('click');
    assert.equal(typeof releaseScan, 'function', 'navigation must start its own summary scan');
    window.innerHeight = 660;
    await harness.listeners.get('resize')();
    releaseScan();
    await new Promise(resolve => setImmediate(resolve));
    assert.equal(model.exploreSummary.groups.range.start, 40);
    assert.match(flatten(harness.mount.template), /Showing 41–80 of 80/,
        'viewport generations must not discard a completed group navigation');
    const previous = harness.mount.querySelectorAll('[data-workbench-explore-action]').find(button =>
        button.getAttribute('data-workbench-explore-group') === 'range'
        && button.getAttribute('data-workbench-explore-action') === 'previous');
    previous.trigger('click');
    await new Promise(resolve => setImmediate(resolve));
    assert.match(flatten(harness.mount.template), /Showing 1–40 of 80/,
        'updated group controls must remain bound in both directions');
    dispose();
});

test('owned row regions initialize from preloaded summaries and stay isolated between mounts', () => {
    const { workbench, window } = loadWorkbench();
    const row = [
        { kind: 'iri', value: 'urn:example:resource' },
        { kind: 'iri', value: 'http://www.w3.org/2000/01/rdf-schema#range' },
        { kind: 'iri', value: 'urn:range:initial' }
    ];
    const model = modelFor('explore', [row]);
    // A row about another resource keeps the windowed table (rows about the resource are grouped by role instead).
    model.metadata = { resource: '<urn:example:other>' };
    model.rowStore = { async read() { return [row]; } };
    const first = windowHarness(workbench, window, model);
    assert.doesNotThrow(() => workbench.views.render(first.mount, model, context, first.renderer),
        'the initial native render must support an already populated row window');
    assert.match(flatten(routeTemplate(workbench, first.mount)), /urn:range:initial/);
    const second = windowHarness(workbench, window, model);
    workbench.views.render(second.mount, model, context, second.renderer);
    const firstNodes = first.nodeValues(routeTemplate(workbench, first.mount));
    const secondNodes = second.nodeValues(routeTemplate(workbench, second.mount));
    assert.ok(firstNodes.length > 1, 'table rows and group summaries must have independent owned roots');
    assert.ok(secondNodes.every(node => !firstNodes.includes(node)), 'mounts must not share DOM regions');
    const pure = workbench.views.pageTemplate(model, context, runtime());
    assert.equal(first.nodeValues(pure).length, 0, 'pure templates must keep their ordinary template representation');
    assert.match(flatten(pure), /urn:range:initial/);
});

function exploreLinks(template, result = []) {
    if (Array.isArray(template)) {
        template.forEach(value => exploreLinks(value, result));
    } else if (template && Array.isArray(template.values)) {
        template.values.forEach(value => exploreLinks(value, result));
    } else if (typeof template === 'string' && template.startsWith('explore?resource=')) {
        result.push(template);
    }
    return result;
}

function runtime() {
    return {
        nothing: '',
        html(strings, ...values) { return { strings: Array.from(strings), values }; },
        render(template, mount) { mount.template = template; }
    };
}

function modelFor(viewId, rows) {
    return {
        viewId,
        vars: ['subject', 'predicate', 'object'],
        rows,
        rowStart: 0,
        rowCount: rows.length,
        rowTopSpacer: 0,
        rowBottomSpacer: 0,
        rowStore: null,
        namespaceMap: {},
        links: [],
        metadata: { resource: '<urn:example:resource>' }
    };
}

const context = { basePath: '/rdf4j-workbench', repositoryId: 'a', workbench: {} };
const terms = [
    [{ kind: 'iri', value: 'http://example.org/resource' }, '<http://example.org/resource>'],
    [{ kind: 'iri', value: 'https://example.org/café%20x?x=1&y=2#fragment' },
        '<https://example.org/café%20x?x=1&y=2#fragment>'],
    [{ kind: 'iri', value: 'urn:example:resource' }, '<urn:example:resource>'],
    [{ kind: 'bnode', value: 'node-1' }, '_:node-1'],
    [{ kind: 'bnode', value: '_:node-2' }, '_:node-2'],
    [{ kind: 'literal', value: 'plain "quoted" \\ value' }, String.raw`"plain \"quoted\" \\ value"`],
    [{ kind: 'literal', value: 'line\n\ttwo\rthree' }, '"line\\n\\ttwo\\rthree"'],
    [{ kind: 'literal', value: 'bonjour', language: 'fr' }, '"bonjour"@fr'],
    [{ kind: 'literal', value: '42', datatype: 'http://www.w3.org/2001/XMLSchema#integer' },
        '"42"^^<http://www.w3.org/2001/XMLSchema#integer>']
];

for (const viewId of ['contexts', 'types', 'explore', 'export']) {
    test(`${viewId} RDF links serialize absolute IRIs and literal syntax before URL encoding`, () => {
        const { workbench } = loadWorkbench();
        const mount = {};
        const model = modelFor(viewId, terms.map(([term]) => [term]));
        model.vars = ['value'];
        workbench.views.render(mount, model, context, runtime());
        const links = exploreLinks(mount.template);
        // Graphs rows also carry an Explore action next to the linked name (plan task M5.2).
        const perRow = viewId === 'contexts' ? 2 : 1;
        assert.equal(links.length, terms.length * perRow);
        terms.forEach(([term, expected], index) => {
            for (let copy = 0; copy < perRow; copy++) {
                const decoded = new URL(links[index * perRow + copy], 'https://workbench.test/').searchParams.get('resource');
                assert.equal(decoded, expected, `${viewId} must preserve ${term.kind} RDF syntax`);
            }
        });
    });
}

test('Explore first row window starts from its actual pending result markup and remains bounded', async () => {
    const { workbench, window } = loadWorkbench();
    const rows = Array.from({ length: 300 }, (_unused, index) => [
        { kind: 'iri', value: `urn:subject:${index}` },
        { kind: 'iri', value: 'urn:predicate' },
        { kind: 'literal', value: String(index) }
    ]);
    const reads = [];
    const model = modelFor('explore', []);
    model.rowCount = rows.length;
    model.rowStore = {
        async read(start, count) { reads.push({ start, count }); return rows.slice(start, start + count); },
        async count() { return rows.length; }
    };
    const listeners = new Map();
    window.innerHeight = 220;
    window.scrollY = 0;
    window.addEventListener = (name, listener) => listeners.set(name, listener);
    window.removeEventListener = name => listeners.delete(name);
    const rowTable = {
        getBoundingClientRect() { return { top: -window.scrollY, height: rows.length * 44 }; }
    };
    const mount = {
        querySelectorAll(selector) {
            const markup = flatten(mount.template);
            return selector.includes('data-workbench-row-table')
                && markup.includes('data-workbench-row-table=true') ? [rowTable] : [];
        }
    };
    const renderer = runtime();
    workbench.views.render(mount, model, context, renderer);
    assert.match(flatten(mount.template), /Loading rows\.\.\./, 'pending results must be visible before the first read');
    const dispose = await workbench.views.bindRowWindows(mount, model, context, renderer);
    assert.ok(model.rows.length > 0, 'pending Explore results must bootstrap the first row window');
    assert.ok(model.rows.length <= 80, 'the first window must stay bounded');
    assert.ok(reads.every(read => read.count < rows.length), 'summary scans and viewport reads must stay bounded');
    assert.doesNotMatch(flatten(mount.template), /Loading rows\.\.\./);
    assert.match(flatten(mount.template), /urn:subject:0/);
    window.scrollY = 145 * 44;
    await listeners.get('scroll')();
    assert.ok(model.rowStart > 0, 'scrolling must read a later result window');
    assert.ok(model.rows.length <= 80, 'later windows must stay bounded');
    dispose();
    assert.equal(listeners.size, 0, 'disposing the route must release window listeners');
});

test('Explore empty resources show an empty result without opening a row window', async () => {
    const { workbench, window } = loadWorkbench();
    let reads = 0;
    let listeners = 0;
    const model = modelFor('explore', []);
    model.rowStore = { async read() { reads++; return []; }, async count() { return 0; } };
    window.addEventListener = () => listeners++;
    const mount = { querySelectorAll() { return []; } };
    const renderer = runtime();
    workbench.views.render(mount, model, context, renderer);
    await workbench.views.bindRowWindows(mount, model, context, renderer);
    assert.match(flatten(mount.template), /No results to display\./);
    assert.doesNotMatch(flatten(mount.template), /Loading rows\.\.\./);
    assert.equal(reads, 0);
    assert.equal(listeners, 0);
});

const countCases = [
    { name: 'short page with a stale total cookie',
        total: 8, returned: 8, limit: 100, offset: 0, cookie: '1', range: 'Rows 1–8 of 8' },
    { name: 'first finite page with no total cookie',
        total: 300, returned: 100, limit: 100, offset: 0, cookie: '', range: 'Rows 1–100 of 300' },
    { name: 'middle finite page',
        total: 300, returned: 100, limit: 100, offset: 100, cookie: '1', range: 'Rows 101–200 of 300' },
    { name: 'last finite page',
        total: 250, returned: 50, limit: 100, offset: 200, cookie: '1', range: 'Rows 201–250 of 250' },
    { name: 'All results with an irrelevant offset',
        total: 300, returned: 300, limit: 0, offset: 200, cookie: '1', range: 'Rows 1–300 of 300' },
    { name: 'empty resource with a stale total cookie',
        total: 0, returned: 0, limit: 100, offset: 0, cookie: '300', range: 'No rows' },
    { name: 'empty page past the final offset',
        total: 300, returned: 0, limit: 100, offset: 400, cookie: '1', range: 'Rows 0 of 300' }
];

for (const example of countCases) {
    test(`Explore native metadata remains authoritative during legacy startup: ${example.name}`, () => {
        const { workbench, context: sandbox } = loadWorkbench();
        const model = modelFor('explore', []);
        model.rowCount = example.returned;
        model.metadata['total-result-count'] = example.total;
        const mount = {};
        workbench.views.render(mount, model, context, runtime());
        const markup = flatten(mount.template);
        const countInput = markup.match(/<input\b[^>]*id="workbench-total-result-count"[^>]*value=([^\s>]+)/);
        const resultCount = { textContent: markup.match(/<span id="explore-result-count">([^<]*)<\/span>/)[1] };
        const resource = '<urn:example:resource>';
        const next = { value: `Next ${example.returned}`, disabled: false };
        const previous = { value: `Previous ${example.returned}`, disabled: false };
        const elements = {
            'explore-result-count': resultCount,
            'explore-resource-summary': { removeAttribute() {} },
            'explore-resource-value': { textContent: '' },
            'explore-pagination': { hidden: false },
            'workbench-total-result-count': countInput ? { value: countInput[1] } : null
        };
        sandbox.document = {
            location: new URL(`https://workbench.test/explore?resource=${encodeURIComponent(resource)}`
                + `&limit_explore=${example.limit}&offset=${example.offset}`),
            getElementById(id) { return elements[id] || null; }
        };
        // The route mount (M7.2) looks for its elements inside the outlet.
        const outlet = {
            querySelectorAll() { return example.returned ? [{}] : []; },
            querySelector(selector) {
                if (/^#[\w-]+$/.test(selector)) { return elements[selector.substring(1)] || null; }
                if (selector.endsWith('.workbench-empty')) { return example.returned ? null : {}; }
                return example.returned ? {} : null;
            }
        };
        const controls = {
            '#resource': { value: resource },
            '#limit_explore': { value: String(example.limit) },
            '#nextX': next,
            '#previousX': previous
        };
        const jquery = selector => {
            if (selector === outlet) {
                return { find: jquery };
            }
            const control = controls[selector] || {};
            return {
                val(value) { if (arguments.length) { control.value = value; return this; } return control.value; },
                prop(name, value) {
                    if (arguments.length > 1) { control[name] = value; return this; }
                    return control[name];
                },
                on() { return this; },
                off() { return this; }
            };
        };
        sandbox.$ = jquery;
        workbench.getQueryStringElements = () => sandbox.document.location.search.substring(1).split('&');
        workbench.getCookie = name => name === 'total_result_count' ? example.cookie : '';
        for (const filename of ['paging.js', 'explore.js']) {
            vm.runInContext(fs.readFileSync(path.join(scripts, filename), 'utf8'), sandbox, { filename });
        }
        workbench.explore.mount(outlet)();
        assert.equal(resultCount.textContent, example.range,
            'the actual total must survive native rendering and legacy startup');
        assert.ok(countInput, 'native Explore must publish the canonical paging metadata input');
        assert.equal(workbench.paging.getTotalResultCount(), example.total);
        assert.equal(previous.disabled, example.offset <= 0 || example.limit <= 0);
        assert.equal(next.disabled, example.limit <= 0 || example.returned < example.limit
            || example.offset + example.returned >= example.total);
    });
}

for (const viewId of ['explore', 'export', 'saved-queries']) {
    test(`${viewId} row-window changes preserve open disclosures and edited controls`, async () => {
        const { workbench, window } = loadWorkbench();
        const rows = Array.from({ length: 300 }, (_unused, index) => [
            { kind: 'iri', value: `urn:subject:${index}` },
            { kind: 'iri', value: 'urn:predicate' },
            { kind: 'literal', value: String(index) }
        ]);
        const model = modelFor(viewId, []);
        model.rowCount = rows.length;
        model.metadata['statement-preview-requested'] = true;
        model.rowStore = { async read(start, count) { return rows.slice(start, start + count); } };
        const harness = windowHarness(workbench, window, model);
        const { mount, renderer, controls, listeners } = harness;
        workbench.views.render(mount, model, context, renderer);
        const dispose = await workbench.views.bindRowWindows(mount, model, context, renderer);
        const regionNodes = harness.nodeValues(mount.template);
        assert.ok(regionNodes.length, 'native routes must give row contents their own DOM roots');
        const outerRenders = harness.renders.filter(target => target === mount).length;
        const firstWindowSize = model.rows.length;
        Object.assign(controls, { expanded: true, resource: '<urn:edited>', limit: '0', showDatatypes: false });
        const edited = { ...controls };
        const focusedControl = mount.querySelector('#edited-control');
        focusedControl.focus();
        window.innerHeight = 660;
        await listeners.get('resize')();
        assert.notEqual(model.rows.length, firstWindowSize, 'resize must produce a genuine row-window change');
        assert.deepEqual(controls, edited, 'disclosure-triggered resize must keep live control state');
        window.scrollY = 145 * 44;
        await listeners.get('scroll')();
        assert.ok(model.rowStart > 0, 'scroll must load a later row window');
        assert.ok(model.rows.length <= 80, 'updated windows must remain bounded');
        assert.deepEqual(controls, edited, 'a later window must keep live control state');
        assert.equal(harness.document.activeElement, focusedControl, 'viewport changes must preserve control focus');
        assert.equal(focusedControl.parentNode, mount, 'the focused control must stay mounted');
        assert.equal(harness.renders.filter(target => target === mount).length, outerRenders,
            'viewport changes must render owned row roots without replacing the route');
        assert.deepEqual(harness.nodeValues(mount.template), regionNodes,
            'the outer template must retain the same owned region nodes');
        const visibleMarkup = flatten(mount.template);
        assert.match(visibleMarkup, new RegExp(`data-workbench-row-index=["']?${model.rowStart}(?:["'\\s>])`),
            'the retained region must show the later row window');
        dispose();
        assert.equal(listeners.size, 0);
    });
}

for (const viewId of ['repositories', 'contexts']) {
    test(`${viewId} scoped row updates preserve route-specific cell rendering`, async () => {
        const { workbench, window } = loadWorkbench();
        const rows = Array.from({ length: 300 }, (_unused, index) => viewId === 'repositories'
            ? [`repository-${index}`, true, false]
            : [{ kind: 'iri', value: `urn:context:${index}` }]);
        const model = modelFor(viewId, []);
        model.vars = viewId === 'repositories' ? ['id', 'readable', 'writeable'] : ['context'];
        model.rowCount = rows.length;
        model.rowStore = { async read(start, count) { return rows.slice(start, start + count); } };
        const harness = windowHarness(workbench, window, model);
        workbench.views.render(harness.mount, model, context, harness.renderer);
        const dispose = await workbench.views.bindRowWindows(harness.mount, model, context, harness.renderer);
        window.scrollY = 145 * 44;
        await harness.listeners.get('scroll')();
        const body = harness.nodeValues(routeTemplate(workbench, harness.mount)).find(node => node.tagName === 'TBODY');
        assert.ok(body, 'the table body must remain an independently owned row root');
        const markup = flatten(body.template);
        if (viewId === 'repositories') {
            assert.ok(markup.includes(`href="/rdf4j-workbench/repositories/repository-${model.rowStart}/summary"`));
            // Access is text (M5.3): only the access that applies is listed.
            assert.match(markup, /<span class="workbench-badge">Read<\/span>/);
            assert.doesNotMatch(markup, />Write</);
        } else {
            const resource = `<urn:context:${model.rowStart}>`;
            assert.ok(markup.includes('explore?resource=' + encodeURIComponent(resource)),
                'later context rows must retain canonical RDF navigation');
        }
        dispose();
    });
}

// Task M5.1 of .agent/execplans/workbench-app-shell-and-critique-fixes-20260930.md: Explore groups rows by role.
test('Explore groups rows by the role the resource plays and shows prefixed names', () => {
    const { workbench } = loadWorkbench();
    const iri = value => ({ kind: 'iri', value });
    const ex = 'http://example.org/';
    const rdfs = 'http://www.w3.org/2000/01/rdf-schema#';
    const item = iri(ex + 'item');
    const graph = iri(ex + 'graph');
    const rows = [
        [item, iri(rdfs + 'label'), { kind: 'literal', value: 'Item label' }, graph],
        [item, iri(ex + 'price'), { kind: 'literal', value: '12', datatype: 'http://www.w3.org/2001/XMLSchema#integer' }, graph],
        [iri(ex + 'other'), iri(ex + 'link'), item, graph],
        [iri(ex + 'a'), item, iri(ex + 'b'), graph],
        [iri(ex + 'x'), iri(ex + 'y'), iri(ex + 'z'), item]
    ];
    const model = modelFor('explore', rows);
    model.vars = ['subject', 'predicate', 'object', 'context'];
    model.namespaceMap = { 'ex:': ex, 'rdfs:': rdfs };
    model.metadata = { resource: 'ex:item', 'explore-resource': '<' + ex + 'item>', 'total-result-count': rows.length };
    const mount = {};
    workbench.views.render(mount, model, context, runtime());
    const markup = flatten(routeTemplate(workbench, mount));
    const group = role => {
        const match = new RegExp(`data-explore-role="?${role}"?[\\s>]`).exec(markup);
        const start = match ? match.index : -1;
        assert.ok(start >= 0, `the ${role} group is rendered`);
        const end = markup.indexOf('</section>', start);
        return markup.substring(start, end);
    };
    assert.match(group('outgoing'), /Outgoing/);
    assert.match(group('incoming'), /Incoming/);
    assert.match(group('predicate'), /Used as predicate/);
    assert.match(group('graph'), /Graph contents/);
    assert.match(group('outgoing'), />rdfs:label</, 'predicates use the repository prefixes');
    assert.match(group('outgoing'), /Graph: ex:graph/, 'one graph is named in the group header');
    const outgoingHeaders = Array.from(group('outgoing').matchAll(/<th[^>]*>([^<]*)<\/th>/g)).map(match => match[1].trim());
    assert.deepEqual(outgoingHeaders, ['Predicate', 'Object'], 'no Graph column when every row shares one graph');
    assert.match(markup, /<h2[^>]*>Item label<\/h2>/, 'the label of the explored resource is the heading');
});

// Plan task M12.1: Explore pages are rendered again in place by the router, so the view (not explore.ts editing the
// rendered DOM) leaves out repeated values and the explored resource itself.
test('Explore lists each class and type once and leaves out the explored resource', () => {
    const { workbench } = loadWorkbench();
    const iri = value => ({ kind: 'iri', value });
    const ex = 'http://example.org/';
    const rdf = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#';
    const rdfs = 'http://www.w3.org/2000/01/rdf-schema#';
    const rows = [
        [iri(ex + 'Sub'), iri(rdfs + 'subClassOf'), iri(ex + 'Class'), iri(ex + 'g1')],
        [iri(ex + 'Sub'), iri(rdfs + 'subClassOf'), iri(ex + 'Class'), iri(ex + 'g2')],
        [iri(ex + 'Class'), iri(rdfs + 'subClassOf'), iri(ex + 'Super'), iri(ex + 'g1')],
        [iri(ex + 'Class'), iri(rdf + 'type'), iri(rdfs + 'Class'), iri(ex + 'g1')],
        [iri(ex + 'Class'), iri(rdf + 'type'), iri(rdfs + 'Class'), iri(ex + 'g2')]
    ];
    const model = modelFor('explore', rows);
    model.vars = ['subject', 'predicate', 'object', 'context'];
    model.namespaceMap = { 'ex:': ex, 'rdfs:': rdfs };
    model.metadata = { resource: 'ex:Class', 'explore-resource': '<' + ex + 'Class>', 'total-result-count': rows.length };
    const mount = {};
    workbench.views.render(mount, model, context, runtime());
    const markup = flatten(routeTemplate(workbench, mount));
    const section = (key) => {
        const start = markup.indexOf(`data-workbench-explore-group=${key}`);
        assert.ok(start >= 0, `the ${key} group is rendered`);
        return markup.substring(start, markup.indexOf('</section>', start));
    };
    const links = (part, term) => part.split('explore?resource=' + encodeURIComponent(term)).length - 1;

    assert.equal(links(section('subClasses'), '<' + ex + 'Sub>'), 1, 'a sub class stated in two graphs is listed once');
    assert.equal(links(section('superClasses'), '<' + ex + 'Super>'), 1);
    assert.equal(links(section('superClasses'), '<' + ex + 'Class>'), 0, 'the explored class is not its own super class');
    const card = markup.substring(markup.indexOf('explore-resource-card__types'));
    assert.equal(links(card.substring(0, card.indexOf('</ul>')), '<' + rdfs + 'Class>'), 1, 'each type is shown once');
});
